"""Compile the vendored HTML verbatim; run after updating the upstream snapshot."""
import json
import re
from pathlib import Path

root = Path(__file__).resolve().parents[3]
catalog = {}
for name in ('moyu-green', 'red-white', 'graphite-minimal', 'zen-whitespace', 'moyu-ticket', 'olive-journal', 'common-components'):
    filename = name + '.md' if name == 'common-components' else 'theme-' + name + '.md'
    source = (root / 'vendor/gzh-design/references' / filename).read_text()
    blocks = []
    heading = variant = ''
    for match in re.finditer(r'^## (.+)|^### (.+)|```html\n([\s\S]*?)```', source, re.M):
        if match[1]:
            heading, variant = match[1], ''
        elif match[2]:
            variant = match[2]
        elif heading.startswith('组件') or name == 'common-components':
            blocks.append({'name': variant or heading, 'section': heading, 'html': match[3].strip()})
    catalog[name] = blocks
out = '// Generated by vendor/gzh-design/scripts/sync_templates.py from vendor/gzh-design.\n'
out += '// Original templates: Copyright 2026 甲木 × 摸鱼小李, AGPL-3.0-or-later.\n'
out += 'export interface GzhTemplate { name: string; section: string; html: string }\n'
out += 'export const gzhTemplates: Record<string, GzhTemplate[]> = ' + json.dumps(catalog, ensure_ascii=False, indent=2) + ';\n'
(root / 'src/gzhTemplates.ts').write_text(out)
print({key: len(value) for key, value in catalog.items()})
